llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Dronedarone has an absolute oral bioavailability of only ~4% in humans under fasting conditions, attributed to extensive first-pass metabolism; this is direct human evidence that a high-molecular-weight, lipophilic, heteroaromatic drug can fall well below the 20% threshold, supporting a low prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Azilsartan has an absolute oral bioavailability of ~58% in humans, showing that some high-molecular-weight, lipophilic drugs can exceed 20%; however, azilsartan is a carboxylic acid with a different transporter and metabolic profile, so this high-bioavailability evidence is only weakly transferable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C54"],
      "claim": "Valomaciclovir stearate, an ester prodrug, achieves >60% oral bioavailability in humans, demonstrating that ester prodrug strategies can improve absorption; nevertheless, the query's specific carbamate/ester prodrug architecture and P-gp liability make this high-F example insufficient to override the low-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, lipophilic ester/carbamate prodrug with multiple physicochemical liabilities and a known tendency toward poor systemic exposure. The most transferable experimental anchor, dronedarone, shows very low absolute oral bioavailability (~4%) in humans due to first-pass metabolism, supporting a low prediction. High-bioavailability analogues such as azilsartan and valomaciclovir stearate are structurally and mechanistically less transferable and do not overcome the low-F evidence. Overall, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule are present in the provided evidence set.",
    "All evidence analogues have low Morgan similarity (~0.2), limiting transferability.",
    "No evidence specifically addresses the query's ester/carbamate prodrug conversion, P-gp efflux, or food effects."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C29"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "dronedarone"
    }
  ],
  "revision_action": "initial"
}

